                                            </div>

                                            {{-- Phone verification section (no $application object) --}}
                                            <div class="grid grid-cols-1 gap-4 my-4" id="phone_verification_container">
                                                <span class="block text-xl font-medium text-center text-gray-800">
                                                    @lang('main.to_your_phone_number')
                                                    <span class="font-semibold text-loan-normal"
                                                        id="phone_verification_phone">
                                                        {{ session('phone') ?? '' }}
                                                    </span>
                                                    @lang('applicant_form.sent_message_with_verification_code_input_to_continue')
                                                </span>

                                                <label class="block mt-4 mb-4">
                                                    <input
                                                        class="w-full px-4 py-3 text-black bg-white border-gray-200 rounded focus:border-loan-dark focus:ring-loan-dark"
                                                        id="phone_verification_input" name="verification_code"
                                                        type="text" inputmode="numeric" autocomplete="one-time-code"
                                                        pattern="[0-9]*" minlength="6" maxlength="6"
                                                        placeholder="@lang('main.verification_code')" required>
                                                </label>

                                                <div x-data="{
                                                    countdown: 60,
                                                    phone: '{{ session('phone') ?? '' }}',
                                                    timer: null,
                                                    init() { this.startCountdown(); },
                                                    startCountdown() {
                                                        this.countdown = 60;
                                                        this.timer = setInterval(() => {
                                                            if (this.countdown > 0) {
                                                                this.countdown--;
                                                            } else {
                                                                clearInterval(this.timer);
                                                            }
                                                        }, 1000);
                                                    },
                                                    sendSMS() {
                                                        this.startCountdown();
                                                        const formData = new FormData();
                                                        formData.append('phone', this.phone);
                                                        formData.append('locale', '{{ app()->getLocale() }}');
                                                
                                                        fetch('/api/landing-form/verification/sms/send-again', {
                                                                method: 'POST',
                                                                body: formData
                                                            })
                                                            .then(response => response.json())
                                                            .then(result => {
                                                                console.log('SMS sent:', result);
                                                            })
                                                            .catch(error => {
                                                                console.error('Error:', error);
                                                            });
                                                    }
                                                }" class="text-sm text-center text-gray-600">
                                                    <!-- Show countdown -->
                                                    <span x-show="countdown > 0">
                                                        @lang('main.send_again') <span x-text="countdown"></span>s
                                                    </span>

                                                    <!-- Show clickable resend link after countdown -->
                                                    <span x-show="countdown === 0"
                                                        class="font-semibold cursor-pointer text-loan-dark hover:underline"
                                                        @click="sendSMS()">
                                                        @lang('main.send_again')
                                                    </span>
                                                </div>
                                            </div>
                                        </div>

                                        <button type="submit"
                                            class="flex flex-row items-center justify-center mt-4 text-lg applicant-form__button disabled:opacity-50 disabled:cursor-not-allowed">
                                            @lang('Confirm')
                                        </button>
                                    </form>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </section>
    </main>
@endsection
